function allRequiredFieldsFilled(e){return e.every(e=>""!==$(e).val().trim())}function getFormValues(e){const r={};return e.forEach(e=>{const s=e.replace("#","");r[s]=$(e).val().trim()}),r}function addPerson(){if(personsData.length>=MAX_PERSONS)return void popUpMessage("center",`Maximum ${MAX_PERSONS} persons allowed.`,"warning");if(!allRequiredFieldsFilled(requiredSelectors))return void popUpMessage("center","Kindly fill all required details of current person","warning");const e=getFormValues(fieldSelectors);personsData.push(e),fieldSelectors.forEach(e=>$(e).val("")),renderPersonCard(e,personsData.length)}function renderPersonCard(e,r){const s=$("#personCardTemplate").clone().removeAttr("id").removeClass("hidden");s.find(".step-number").text(r);const n=`\n    <div><strong>Name:</strong> ${e.firstName} ${e.middleName||""} ${e.lastName}</div>\n    <div><strong>DOB:</strong> ${formatDateToDDMMYYYY(e.dob)}</div>\n    <div><strong>Passport:</strong> ${e.passportNumber}</div>\n    <div><strong>Email:</strong> ${e.email}</div>\n    <div><strong>Mobile:</strong> ${e.mobile}</div>\n  `;s.find(".person-info").html(n),$("#personStepsContainer").append(s)}const MAX_PERSONS=10,personsData=[],fieldSelectors=["#firstName","#middleName","#lastName","#dob","#passportNumber","#passportExpiry","#email","#mobile","#address"],requiredSelectors=["#firstName","#lastName","#dob","#passportNumber","#passportExpiry","#email","#mobile","#address"];$("#addNewPersonBtn").on("click",function(e){e.preventDefault(),addPerson()});